/* Gallery in Personal */


/* Gallery in Personal */
.gallery {
  height: 60%;
  width: 100%;
  display: flex;
  margin: 5% auto 0;
  box-sizing: border-box;
}

.image-box {
  margin: 0 .5%;
  flex-grow: 1;
  flex-basis: 0;
  transition: .5s;
}

.image-box img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: .5s;
}

.image-box:hover {
  flex-basis: 50%;
}

.active-image {
  flex-basis: 50%;
}

.gallery:hover .active-image {
  flex-basis: 0;
}

.image-box:nth-child(1):hover {
  flex-basis: 50%
}



.centered-content>div:first-child {
  margin-left: auto;
  margin-right: auto
}
.text-long .media-entity-wrapper.video {
  float: none;
  position: relative
}
.text-long .media-entity-wrapper.video:before {
  display: block;
  content: "";
  width: 100%;
  padding-top: 56.25%
}
.text-long .media-entity-wrapper.video>img, .text-long .media-entity-wrapper.video>video {
  -o-object-fit: cover;
  object-fit: cover
}
.text-long .media-entity-wrapper.video>* {
  position: relative;
  z-index: 5
}
.text-long .media-entity-wrapper.video>div {
  position: absolute;
  z-index: 1;
  width: 100%;
  height: 100%;
  left: 0;
  bottom: 0
}
.text-long .media-entity-wrapper.video iframe {
  height: 100%;
  min-height: unset;
  width: 100%
}
