}

.awe-weather-bubble {
  color: #666;
  text-align: center;
  text-shadow: none;
  font-weight: bold;
  font-size: 10px;
  position: absolute;
  top: -32px;
  right: -48px;
  width: 130px;
  padding: 5px;
  background: #fff;
  border-radius: 3px;
  border: #ccc solid 1px;
