  border-style: solid;
  border-width: 10px 10px 0;
  border-color: #fff transparent;
  display: block;
  width: 0;
  z-index: 1;
  margin-left: -10px;
  bottom: -10px;
  left: 50%;
}
.awe-weather-bubble:before {
  content: '';
  position: absolute;
  border-style: solid;
  border-width: 10px 10px 0;
  border-color: #ccc transparent;
  display: block;
  width: 0;
  z-index: 0;
