  transform: translateY(200px);
  opacity: 0;
  transition: all 0.3s ease-out;
  transition-property: opacity, transform;
}
.accordion__overlay {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(180deg, rgba(15, 15, 15, 0) 0%, #111111 100%);
