/* Table of contents in Miscellaneous - PC Version - VERY CLOSE TO EDGE */
.sidebar-mis {
  position: fixed;
  top: 210px;
  right: 2px; /* Almost off-screen - just 2px from edge */
  width: 140px; /* Narrow width to fit in tight space */
  max-height: 70vh;
  overflow-y: auto;
  background-color: #f9f9f9;
  padding: 10px 8px; /* Reduced padding */
  border-radius: 4px 0 0 4px; /* Rounded on left side only */
  box-shadow: -2px 0 10px rgba(0, 0, 0, 0.1); /* Shadow on left side */
  z-index: 999;
  border: 1px solid #e0e0e0;
  border-right: none; /* No border on right edge */
  transition: all 0.3s ease;
}

/* Expand slightly on hover to reveal more content */
.sidebar-mis:hover {
  right: 0;
  width: 160px;
  box-shadow: -3px 0 15px rgba(0, 0, 0, 0.15);
  border-right: 1px solid #e0e0e0;
  border-radius: 4px;
}

.sidebar-mis h4 {
  margin-top: 0;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 1px solid #b1040e;
  color: #333;
  font-size: 18px;
  font-weight: bold;
  line-height: 1.1;
  text-align: center;
}

.sidebar-mis a {
  display: block;
  color: #555;
  padding: 5px 0;
  text-decoration: none;
  font-size: 16px;
  font-weight: normal;
  line-height: 1.2;
  border-left: 1px solid transparent;
  padding-left: 5px;
  margin-left: -5px;
  transition: all 0.2s ease;
  word-wrap: break-word;
}

.sidebar-mis a:hover,
.sidebar-mis a:focus {
  color: #b1040e;
  border-left: 1px solid #b1040e;
  background-color: rgba(177, 4, 14, 0.05);
  transform: translateX(1px);
}

.sidebar-mis a:active {
  background-color: rgba(177, 4, 14, 0.1);
}

/* Custom scrollbar - very thin */
.sidebar-mis::-webkit-scrollbar {
  width: 4px;
}

.sidebar-mis::-webkit-scrollbar-track {
  background: #f1f1f1;
}

.sidebar-mis::-webkit-scrollbar-thumb {
  background: #b1040e;
  border-radius: 2px;
}

.sidebar-mis::-webkit-scrollbar-thumb:hover {
  background: #8c030b;
}

/* ============== MOBILE/TABLET: HIDDEN SIDEBAR WITH TOUCH HANDLE ============== */
@media screen and (max-width: 1024px) {
  /* Default state: completely hidden off-screen */
  .sidebar-mis {
    position: fixed;
    top: 0;
    right: -280px; /* Hidden completely off-screen */
    bottom: 0;
    width: 280px; /* Fixed width for mobile drawer */
    max-width: 85vw; /* Maximum width for very small screens */
    max-height: 100vh !important;
    height: 100vh;
    padding: 20px 15px !important;
    border-radius: 0 !important;
    border-right: 1px solid #e0e0e0 !important;
    box-shadow: 5px 0 25px rgba(0, 0, 0, 0.15) !important;
    transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    z-index: 1000;
    overflow-y: auto;
  }
  
  /* Active state when opened */
  .sidebar-mis.mobile-active {
    right: 0 !important;
  }
  
  /* Touch handle to open sidebar */
  .sidebar-touch-handle {
    position: fixed;
    top: 50%;
    right: 0;
    transform: translateY(-50%);
    width: 40px;
    height: 80px;
    background-color: #b1040e;
    border-radius: 10px 0 0 10px;
    z-index: 999;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    box-shadow: -2px 0 10px rgba(177, 4, 14, 0.3);
    transition: all 0.3s ease;
  }
  
  .sidebar-touch-handle::before {
    content: '☰';
    color: white;
    font-size: 20px;
    font-weight: bold;
  }
  
  .sidebar-touch-handle:hover {
    width: 45px;
    background-color: #8c030b;
  }
  
  /* Close button inside sidebar */
  .sidebar-close-btn {
    position: absolute;
    top: 15px;
    left: 15px;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background-color: #f5f5f5;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 20px;
    color: #333;
    cursor: pointer;
    z-index: 10;
    border: none;
  }
  
  .sidebar-close-btn:hover {
    background-color: #e0e0e0;
  }
  
  /* Adjust sidebar content for mobile */
  .sidebar-mis h4 {
    margin-top: 40px; /* Space for close button */
    text-align: center;
    margin-bottom: 20px;
    font-size: 18px;
  }
  
  .sidebar-mis a {
    padding: 12px 15px !important;
    font-size: 15px;
    border-left: 3px solid transparent;
    margin-left: 0;
    margin-bottom: 5px;
    border-bottom: none;
    min-height: 44px;
    display: flex;
    align-items: center;
  }
  
  .sidebar-mis a:hover,
  .sidebar-mis a:focus {
    border-left: 3px solid #b1040e;
    border-bottom: none;
    transform: none;
    background-color: rgba(177, 4, 14, 0.05);
  }
  
  /* Overlay when sidebar is open */
  .sidebar-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: rgba(0, 0, 0, 0.5);
    z-index: 999;
    opacity: 0;
    visibility: hidden;
    transition: opacity 0.3s ease, visibility 0.3s ease;
  }
  
  .sidebar-overlay.active {
    opacity: 1;
    visibility: visible;
  }
  
  /* Larger scrollbar for touch devices */
  .sidebar-mis::-webkit-scrollbar {
    width: 6px;
  }
}

/* Tablet specific (768px - 1024px) */
@media screen and (min-width: 768px) and (max-width: 1024px) {
  .sidebar-mis {
    width: 320px;
