    align-items: center;
    padding: 4rem 3rem;
}

/* ===== PHOTO CARD ===== */

.photo-card {
    position: relative;
    width: 100%;
    aspect-ratio: 7 / 9;
    border-radius: 8px;
    box-shadow: 0 20px 30px -12px rgba(0, 0, 0, 0.25);
    overflow: hidden;
    cursor: pointer;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    text-decoration: none;
    transition: all 0.3s ease;
}

/* Important: Prevent image distortion */
.photo-card::before {
    content: '';
    position: absolute;
    inset: 0;
    background-size: cover;     /* keeps correct proportions */
    background-position: center;
    background-repeat: no-repeat;
    transition: transform 0.5s ease;
    z-index: 1;
}

/* LEFT IMAGE */
.img-left::before {
    background-image: url('https://picsum.photos/900/1200?random=1');
}

/* RIGHT IMAGE */
.img-right::before {
    background-image: url('https://picsum.photos/900/1200?random=2');
}

.photo-card:hover {
    transform: scale(1.02) translateY(-6px);
}

.photo-card:hover::before {
    transform: scale(1.08);
}

/* ===== GRADIENT OVERLAY ===== */

.photo-card::after {
    content: '';
    position: absolute;
    bottom: 0;
    width: 100%;
    height: 45%;
    background: linear-gradient(to top, rgba(0,0,0,0.75), transparent);
    z-index: 2;
}

/* ===== TEXT ===== */

.text-bottom {
    position: relative;
    z-index: 10;
    width: 100%;
    text-align: center;
    padding: 1.8rem 1.2rem 2rem;
    color: white;
    text-shadow: 0 2px 6px rgba(0,0,0,0.7);
}

.line-1 {
    font-size: 1.8rem;
    font-weight: 600;
    letter-spacing: 0.2rem;
    text-transform: uppercase;
}

.line-2 {
    font-family: 'Times New Roman', serif;
    font-size: 1.4rem;
    font-style: italic;
}

.line-3 {
    font-size: 1rem;
    letter-spacing: 0.15rem;
    text-transform: uppercase;
    opacity: 0.9;
}

/* ===== LIGHTBOX ===== */

.lightbox {
    position: fixed;
    inset: 0;
    background: rgba(0,0,0,0.9);
    display: none;
    justify-content: center;
    align-items: center;
    z-index: 999;
    padding: 2rem;
}

.lightbox:target {
    display: flex;
}

.lightbox img {
    max-width: 90%;
    max-height: 90vh;
    object-fit: contain; /* VERY IMPORTANT — no stretching */
    border-radius: 6px;
}

.lightbox-close {
    position: absolute;
    top: 30px;
    right: 40px;
    font-size: 2rem;
    color: white;
    text-decoration: none;
}

/* ===== RESPONSIVE ===== */

@media (max-width: 900px) {
    .two-photo-row {
        gap: 1.5rem;
    }
}

@media (max-width: 650px) {
    .two-photo-row {
        grid-template-columns: 1fr;
        max-width: 450px;
    }
}


